/* @socom-skeleton body GetMapByIndex__7CAiMapsCFUi */
CAiMap * CAiMaps::GetMapByIndex(unsigned int index) const
{
	/* 0x19d3c0 (inlined by the map-id lookups below): NULL past the end */
	if (index >= size())
		return NULL;

	const_iterator i = begin();

	while (index-- != 0)
		++i;

	return (CAiMap*)*i;
}

